#!/usr/bin/env bash
# FontFerry reassembly (protocol fonttext/1) — pure bash, no jq/python.
#
# Usage:
#   sh rebuild.sh <MANIFEST.txt> <chunk-dir> <out.woff2>
#
# Behavior:
#   - reads MANIFEST.txt (line-based, generated by builder/build.mjs)
#   - for each chunk index: strips the two '# ...' framing lines from the
#     chunk page, removes ALL whitespace (incl. CRLF), base64-decodes it
#     into out.part.<i>, verifies per-chunk SHA-256
#   - concatenates parts in order, verifies whole-file SHA-256
#   - resume-aware: an existing, already-verified part is reused (no
#     re-decode) — delete part files to force re-decode
#   - exits non-zero with the offending chunk index on any mismatch
set -eu

MANIFEST="${1:?usage: rebuild.sh <MANIFEST.txt> <chunk-dir> <out.woff2>}"
CHUNKDIR="${2:?chunk dir required}"
OUT="${3:?output path required}"

[ -f "$MANIFEST" ] || { echo "rebuild: manifest not found: $MANIFEST" >&2; exit 1; }
[ -d "$CHUNKDIR" ] || { echo "rebuild: chunk dir not found: $CHUNKDIR" >&2; exit 1; }
[ -e "$OUT" ] && [ -d "$OUT" ] && { echo "rebuild: output path is a directory: $OUT" >&2; exit 1; }

WORD() { grep -E "^$1=" "$MANIFEST" | head -n1 | cut -d= -f2-; }

WHOLE=$(WORD whole_file_sha256)
N=$(WORD chunk_count)
[ -n "$WHOLE" ] && [ -n "$N" ] || { echo "rebuild: manifest unreadable (missing whole_file_sha256/chunk_count)" >&2; exit 1; }

PARTDIR=$(dirname "$OUT")

echo "rebuild: $N chunk(s), whole-file sha256=$WHOLE"

: > "$OUT.tmp"
i=0
while [ "$i" -lt "$N" ]; do
  csha=$(WORD "chunk_${i}_sha256")
  cfile=$(WORD "chunk_${i}_file")
  [ -n "$csha" ] && [ -n "$cfile" ] || { echo "rebuild: manifest missing entry for chunk $i" >&2; exit 1; }

  part="$PARTDIR/$(basename "$OUT").part.$i"
  need=1
  if [ -f "$part" ]; then
    have=$(sha256sum "$part" | awk '{print toupper($1)}')
    [ "$have" = "$csha" ] && need=0
  fi

  if [ "$need" = 1 ]; then
    src="$CHUNKDIR/$cfile"
    [ -f "$src" ] || { echo "rebuild: chunk file missing: $src" >&2; exit 1; }
    # strip framing lines, drop all whitespace, decode
    grep -v '^#' "$src" | tr -d ' \t\r\n' | base64 -d > "$part"
    have=$(sha256sum "$part" | awk '{print toupper($1)}')
    if [ "$have" != "$csha" ]; then
      echo "rebuild: chunk $i HASH MISMATCH ($cfile) expected=$csha got=$have" >&2
      exit 1
    fi
    echo "rebuild: chunk $i ok ($cfile)"
  else
    echo "rebuild: chunk $i reused verified part"
  fi
  cat "$part" >> "$OUT.tmp"
  i=$((i+1))
done

mv "$OUT.tmp" "$OUT"
actual=$(sha256sum "$OUT" | awk '{print toupper($1)}')
if [ "$actual" = "$WHOLE" ]; then
  echo "OK $OUT sha256=$actual"
else
  echo "FAIL $OUT sha256=$actual expected=$WHOLE" >&2
  exit 1
fi
